<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Share Interview Experience</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f8fd;color:#102445;font-family:Inter,system-ui,sans-serif}.wrap{width:min(900px,calc(100% - 32px));margin:45px auto 80px}.panel{background:#fff;border:1px solid #d6e3f2;border-radius:18px;padding:28px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{display:grid;gap:7px;font-weight:750}input,select,textarea{width:100%;border:1px solid #bdcde2;border-radius:9px;padding:12px;font:inherit}textarea{min-height:110px;resize:vertical}.round{border-left:4px solid #2c73ee}.btn{border:0;border-radius:9px;padding:13px 18px;background:#286df0;color:#fff;font-weight:850;cursor:pointer}.btn.secondary{background:#e9f1ff;color:#1556b3}.errors{background:#fee2e2;color:#991b1b;padding:15px;border-radius:10px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Share your interview experience</h1><p>Your submission stays private until an administrator reviews and approves it.</p>@if($errors->any())<div class="errors"><b>Please correct these fields:</b><ul>@foreach($errors->all() as $error)<li>{{$error}}</li>@endforeach</ul></div>@endif<form method="post" action="{{route('company.experiences.store')}}">@csrf<div class="panel grid"><label>Company *<select name="company_id" required><option value="">Select company</option>@foreach($companies as $company)<option value="{{$company->id}}" @selected(old('company_id',$selectedCompany)==$company->id)>{{$company->name}}</option>@endforeach</select></label><label>Role *<input name="role_name" value="{{old('role_name')}}" required placeholder="Software Engineer"></label><label>Department<input name="department" value="{{old('department')}}" placeholder="Engineering"></label><label>Experience level *<input name="experience_level" value="{{old('experience_level')}}" required placeholder="2–5 years"></label><label>Location *<input name="location" value="{{old('location')}}" required placeholder="Bengaluru, India"></label><label>Interview date<input type="date" name="interview_date" value="{{old('interview_date')}}" max="{{now()->toDateString()}}"></label><label>Application source<input name="application_source" value="{{old('application_source')}}" placeholder="Referral, careers page..."></label><label>Result *<select name="result" required>@foreach(['selected','rejected','offer','waiting','withdrew'] as $v)<option @selected(old('result')===$v)>{{$v}}</option>@endforeach</select></label><label>Overall difficulty *<select name="difficulty" required>@foreach(['easy','medium','hard','very_hard'] as $v)<option value="{{$v}}" @selected(old('difficulty')===$v)>{{ucwords(str_replace('_',' ',$v))}}</option>@endforeach</select></label><label>Process duration (days)<input type="number" name="duration_days" value="{{old('duration_days')}}" min="0" max="730"></label></div><div class="panel"><label>Overall experience *<textarea name="overall_experience" required minlength="40" maxlength="10000">{{old('overall_experience')}}</textarea></label><label style="margin-top:15px">Preparation advice<textarea name="preparation_advice" maxlength="6000">{{old('preparation_advice')}}</textarea></label></div><div id="rounds"></div><button type="button" class="btn secondary" id="add-round">+ Add interview round</button><div class="panel grid" style="margin-top:18px"><h2 style="grid-column:1/-1">Optional compensation</h2><label>Currency<select name="currency">@foreach(['INR','USD','EUR','GBP','AED','SGD','CAD','AUD'] as $c)<option>{{$c}}</option>@endforeach</select></label><label>Experience years<input type="number" step="0.1" min="0" name="experience_years"></label><label>Base salary<input type="number" step="0.01" min="0" name="base_salary"></label><label>Bonus<input type="number" step="0.01" min="0" name="bonus"></label><label>Stock value<input type="number" step="0.01" min="0" name="stock_value"></label><label>Total compensation<input type="number" step="0.01" min="0" name="total_compensation"></label><label style="grid-column:1/-1">Notes<textarea name="salary_notes"></textarea></label></div><button class="btn">Submit for review</button></form></main><template id="round-template"><section class="panel round"><h2>Round <span class="number"></span></h2><div class="grid"><label>Round name *<input data-name="round_name" required placeholder="Technical / DSA"></label><label>Round type *<select data-name="round_type" required>@foreach(['recruiter','aptitude','coding','dsa','system_design','machine_coding','project','managerial','behavioral','hr','technical','role_specific'] as $v)<option value="{{$v}}">{{ucwords(str_replace('_',' ',$v))}}</option>@endforeach</select></label><label>Duration (minutes)<input data-name="duration_minutes" type="number" min="1" max="600"></label><label>Difficulty<select data-name="difficulty"><option value="">Not specified</option>@foreach(['easy','medium','hard','very_hard'] as $v)<option value="{{$v}}">{{ucwords(str_replace('_',' ',$v))}}</option>@endforeach</select></label></div><label>Description *<textarea data-name="description" required></textarea></label><label>Topics (one per line)<textarea data-name="topics"></textarea></label><label>Questions asked (one per line)<textarea data-name="questions"></textarea></label><label>Candidate notes<textarea data-name="candidate_experience"></textarea></label><button type="button" class="btn secondary remove">Remove round</button></section></template><script>const box=document.querySelector('#rounds'),tpl=document.querySelector('#round-template');function renumber(){[...box.children].forEach((el,i)=>{el.querySelector('.number').textContent=i+1;el.querySelectorAll('[data-name]').forEach(f=>f.name=`rounds[${i}][${f.dataset.name}]`)})}function add(){const node=tpl.content.firstElementChild.cloneNode(true);node.querySelector('.remove').onclick=()=>{if(box.children.length>1){node.remove();renumber()}};box.append(node);renumber()}document.querySelector('#add-round').onclick=add;add();</script></body></html>
